if (!installed()) {
    http_response_code(503);
    ?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Emlak 54 Yönetim Paneli</title><meta name="robots" content="noindex,nofollow"><link rel="stylesheet" href="<?=e(asset_vurl('admin.css'))?>"></head><body class="admin-login-page"><main class="login-card"><div class="admin-brand">Emlak <span>54</span></div><h1>Yönetim paneli henüz kurulmadı.</h1><p>Önce veritabanı bilgilerini <code>config.php</code> içinde ayarlayın, ardından ilk yönetici hesabını oluşturmak için kurulumu başlatın.</p><a class="admin-btn admin-btn-primary" href="install.php">Güvenli kurulumu başlat</a></main></body></html><?php
    exit;
}

if ($_SERVER['REQUEST_METHOD']==='POST' && (string)($_POST['action']??'')==='login' && !hash_equals(csrf_token(), (string)($_POST['csrf_token'] ?? ''))) {
    log_security_event('csrf_failed', 'warning', 'Yönetici giriş formu güvenlik anahtarı geçersiz');
    $loginError = 'Oturum süresi doldu. Güvenlik için sayfa yenilendi; lütfen tekrar giriş yapın.';
} elseif ($_SERVER['REQUEST_METHOD']==='POST' && (string)($_POST['action']??'')==='login') {
    $username=trim((string)($_POST['username']??''));
    $password=(string)($_POST['password']??'');
    if (!rate_limit('admin-login',8,900)) {
        log_security_event('login_rate_limited','high','Yönetici giriş istek sınırına ulaştı');
        $loginError='Çok fazla giriş denemesi. 15 dakika sonra tekrar deneyin.';
    } else {
        try {
            $pdo=db();
            $accountKey=hash('sha256',strtolower($username));
            $accountLimit=$pdo->prepare("SELECT COUNT(*) FROM security_events WHERE event_type='login_failed' AND detail=? AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 15 MINUTE)");
            $accountLimit->execute(['account='.$accountKey]);
            if ((int)$accountLimit->fetchColumn()>=12) {
                $loginError='Bu kullanıcı adı için geçici güvenlik kilidi etkin. Bir süre sonra tekrar deneyin.';
                log_security_event('account_lockout','high','Yönetici hesabına ait geçici kilit tetiklendi');
            } else {
                $stmt=$pdo->prepare('SELECT id,username,password_hash,display_name,is_active FROM admins WHERE username=? LIMIT 1');
                $stmt->execute([$username]);$admin=$stmt->fetch();
                $valid=$admin && (int)$admin['is_active']===1 && password_verify($password,(string)$admin['password_hash']);
                if (!$valid) {
                    log_security_event('login_failed','warning','account='.$accountKey);
                    $count=$pdo->prepare("SELECT COUNT(*) FROM security_events WHERE ip_address=? AND event_type='login_failed' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 15 MINUTE)");$count->execute([client_ip()]);
                    if ((int)$count->fetchColumn()>=8) { auto_ban(client_ip(),'Çok sayıda başarısız yönetici girişi',24);log_security_event('auto_ip_ban','high','Başarısız giriş denemeleri nedeniyle geçici engel'); }
                    // Deliberately use the same message for unknown users and incorrect passwords.
                    $loginError='Kullanıcı adı veya parola hatalı.';
                    usleep(250000);
                } else {
                    if (password_needs_rehash((string)$admin['password_hash'],defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT)) {
                        $rehash=password_hash($password,defined('PASSWORD_ARGON2ID')?PASSWORD_ARGON2ID:PASSWORD_DEFAULT);
                        if($rehash)$pdo->prepare('UPDATE admins SET password_hash=? WHERE id=?')->execute([$rehash,(int)$admin['id']]);
                    }
                    session_regenerate_id(true);
                    $_SESSION['admin_id']=(int)$admin['id'];$_SESSION['admin_name']=(string)$admin['display_name'];$_SESSION['admin_login_at']=time();$_SESSION['admin_last_activity']=time();
                    $_SESSION['csrf_token']=bin2hex(random_bytes(32));
                    $pdo->prepare('UPDATE admins SET last_login_at=UTC_TIMESTAMP() WHERE id=?')->execute([(int)$admin['id']]);
                    log_security_event('login_success','info','Yönetici oturumu açıldı');
                    log_admin_action('admin_login','admin',(int)$admin['id']);
                    header('Location: emlak-admin.php');exit;
                }
            }
        } catch(Throwable $ex) {
            error_log('[Emlak54 admin login] '.$ex->getMessage());
            $loginError=app_config('app_env')==='development'?$ex->getMessage():'Giriş servisi şu anda kullanılamıyor. Sunucu ve veritabanı ayarlarını kontrol edin.';
        }
    }
}

